from urllib.parse import urlparse, urlunparse
def base_url(u):
    try:
        p=urlparse(u)
        # remove query and fragment
        return urlunparse((p.scheme,p.netloc,p.path,'','',''))
    except Exception:
        return u
df['URL_base']=df['URL'].apply(base_url)
