from urllib.parse import urlparse
def ref_category(ref):
    if pd.isna(ref) or ref.strip()=="":
        return "Direct/Unknown"
    r=ref.strip()
    if r.startswith("android-app://") or "mail.google.com" in r or "mail." in r:
        return "Email"
    try:
        net=urlparse(r).netloc.lower()
    except Exception:
        net=""
    if "academia.edu" in net or "cloudfront.net" in net:
        return "Academia/Platform"
    if "google." in net or "scholar.google" in r:
        # distinguish scholar
        if "scholar.google" in r:
            return "Search: Google Scholar"
        return "Search: Google"
    if "duckduckgo" in net:
        return "Search: DuckDuckGo"
    if "bing.com" in net or "search.yahoo" in net:
        return "Search: Other"
    if "facebook.com" in net or "lm.facebook" in net:
        return "Social"
    if "perplexity.ai" in net:
        return "AI tools"
    return "Other"
df['ref_cat']=df['Referer'].apply(ref_category)
df['ref_cat'].value_counts()

